(function(root){
  'use strict';
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let admin=false,ownerAccess=false,accessPermissions=[],checking=false,retryRequested=false;
  function isAdmin(){return admin;}
  async function client(){if(!window.YamaAccountUI?.isSignedIn())throw new Error('Přihlas se účtem s oprávněním do Yama administrace.');return window.YamaPortalIntegration.sharedClient(location.origin);}
  async function verify(){const sb=await client();const {data:userData,error:userError}=await sb.auth.getUser();if(userError||!userData?.user)throw new Error('Přihlášení už není platné. Přihlas se znovu.');const access=await invoke(sb,'access-status');if(access.is_owner!==true&&!(access.permissions||[]).length)throw new Error('Tento účet nemá oprávnění do Yama administrace.');return {sb,user:userData.user,access};}
  async function invoke(sb,action,extra={}){const {data,error}=await sb.functions.invoke('yamachat-snapshot-v11',{body:{action,...extra}});if(error)throw new Error(data?.error||'Serverovou operaci se nepodařilo dokončit.');if(data?.error)throw new Error(data.error);return data||{}}
  async function hostAdminRequest(sb,route,payload){const {data,error}=await sb.auth.getSession();const token=data?.session?.access_token;if(error||!token)throw new Error('Přihlášení už není platné.');const response=await fetch('https://yamahost.yamachat.eu/api/yamahost/'+route,{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify(payload),cache:'no-store',redirect:'error'});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'Řídicí služba YamaHostu akci odmítla.');return result;}
  async function init(){if(checking){retryRequested=true;return;}checking=true;const previous=admin;try{const {access}=await verify();ownerAccess=access.is_owner===true;accessPermissions=access.permissions||[];admin=true;}catch{admin=false;ownerAccess=false;accessPermissions=[];}finally{checking=false;if(previous!==admin)window.dispatchEvent(new Event('yama-admin-state'));if(retryRequested){retryRequested=false;void init();}}}
  function markup(){return `<section class="panel page-content owner-admin"><p class="eyebrow">VLASTNICKÁ SPRÁVA</p><h2>Yama Admin Center</h2><p class="muted">Přístup ověřuje serverová role vlastníka. Soubory jsou zde viditelné jen jako metadata; obsah soukromých souborů se nezobrazuje.</p><div class="admin-state" role="status">Ověřuji roli vlastníka…</div><div class="admin-content" hidden><div class="admin-stats"><article class="admin-stat"><span>Účty Yamachat</span><strong data-admin-user-count>—</strong><small data-admin-user-count-note>ověřuji na serveru</small></article><article class="admin-stat"><span>Oprávnění</span><strong data-admin-role>ověřeno</strong><small>role potvrzena serverem</small></article></div><section class="admin-section" data-permission="users.read"><h3>Uživatelé</h3><p class="caption">Seznam vrací server až po kontrole role vlastníka. Hesla a přihlašovací tokeny se nezobrazují. Vlastník vidí ověřené využití YamaHostu každým účtem. Ostatní správci osobní kvóty nevidí.</p><p class="caption" data-yamahost-storage-status role="status">Úložiště YamaHostu je dostupné pouze vlastníkovi.</p><div class="admin-user-controls"><label for="admin-user-search">Hledat uživatele<input id="admin-user-search" type="search" autocomplete="off" placeholder="Jméno, e-mail nebo ID"></label><label for="admin-user-sort">Seřadit podle<select id="admin-user-sort"><option value="recent">Poslední přihlášení</option><option value="newest">Nejnovější registrace</option><option value="name">Jméno A–Z</option><option value="email">E-mail A–Z</option><option value="storage">Spotřeba YamaHostu</option></select></label></div><p class="form-status" data-user-admin-status role="status"></p><button class="secondary" type="button" data-role-audit>Historie změn rolí</button><div data-role-audit-content></div><button class="secondary" type="button" data-user-audit>Historie úkonů účtů</button><div data-user-audit-content></div><div class="admin-users" data-admin-users><p>Načítám…</p></div></section><section class="admin-section" data-permission="storage.read"><h3>Úložiště Yamachat</h3><p class="caption">Přehled Supabase Storage: názvy, velikosti a limity úložišť. Obsah soukromých souborů ani jejich odkazy se nenačítají. Mazání vyžaduje dvě potvrzení a uložený audit.</p><div class="admin-storage-actions"><button class="secondary" type="button" data-storage-refresh>Načíst přehled</button><button class="secondary" type="button" data-storage-audit>Historie údržby</button></div><p class="form-status" data-storage-status role="status">Přehled ještě nebyl načten.</p><div data-storage-content></div></section><section class="admin-section" data-owner-only><h3>Oznámení uživatelům</h3><p class="caption">Zpráva se uloží do schránky všech dostupných profilů Yamachat až po tvém potvrzení.</p><form data-admin-broadcast><label for="admin-title">Nadpis</label><input id="admin-title" name="title" maxlength="120" required><label for="admin-body">Zpráva</label><textarea id="admin-body" name="body" rows="5" maxlength="4000" required></textarea><label for="admin-kind">Typ oznámení</label><select id="admin-kind" name="kind"><option value="info">Informace</option><option value="important">Důležité</option><option value="warning">Upozornění</option></select><label class="admin-confirm"><input type="checkbox" name="confirm" required>Rozumím, že tato zpráva bude odeslána všem uživatelům Yamachat.</label><button class="primary" type="submit">Odeslat všem uživatelům</button><p class="form-status" data-admin-status role="status"></p></form></section><section class="admin-section" data-owner-only><h3>Moderace Yamachat</h3><p class="caption">Stávající serverově ověřené nástroje moderace zůstávají v Yamachatu.</p><a class="secondary" href="#yamachat">Otevřít Yamachat a jeho správu →</a></section></div></section>`;}
  function renderUsers(rows){
    const target=document.querySelector('[data-admin-users]'),count=document.querySelector('[data-admin-user-count]'),note=document.querySelector('[data-admin-user-count-note]');
    if(!target)return;
    count.textContent=String(rows.length);
    note.textContent=rows.length>=1000?'výpis omezen na první 1 000 účtů':'účtů vráceno serverem';
    target.dataset.userRows=JSON.stringify(rows);
    const query=(document.querySelector('#admin-user-search')?.value||'').trim().toLocaleLowerCase('cs-CZ');
    const sort=document.querySelector('#admin-user-sort')?.value||'recent';
    const filtered=rows.filter(user=>[user.display_name,user.username,user.email,user.id].some(value=>String(value||'').toLocaleLowerCase('cs-CZ').includes(query)));
    const time=value=>{const parsed=Date.parse(value||'');return Number.isFinite(parsed)?parsed:0;};
    filtered.sort((a,b)=>{if(sort==='storage'){const av=Number.isFinite(a.yamahostStorage?.usedBytes)?a.yamahostStorage.usedBytes:null,bv=Number.isFinite(b.yamahostStorage?.usedBytes)?b.yamahostStorage.usedBytes:null;if(av===null)return bv===null?0:1;if(bv===null)return -1;return bv-av;}return sort==='name'?String(a.display_name||a.username||a.email||'').localeCompare(String(b.display_name||b.username||b.email||''),'cs-CZ'):sort==='email'?String(a.email||'').localeCompare(String(b.email||''),'cs-CZ'):sort==='newest'?time(b.created_at)-time(a.created_at):time(b.last_sign_in_at)-time(a.last_sign_in_at)});
    const permissionLabels=[['users.read','Číst uživatele'],['users.suspend','Pozastavit účty'],['users.reset_password','Poslat obnovu hesla'],['storage.read','Číst metadata úložiště'],['storage.delete','Mazat soubory']];
    target.innerHTML=filtered.length?'<ul>'+filtered.map(user=>{
      const role=user.role||'USER',isOwner=role==='OWNER',display=user.display_name||user.username||'Uživatel';
      const permissions=permissionLabels.map(([value,label])=>'<label><input type="checkbox" data-role-permission="'+esc(value)+'" '+((user.permissions||[]).includes(value)?'checked ':'')+'>'+esc(label)+'</label>').join('');
      const roleEditor=isOwner?'<details class="admin-role-editor"><summary>Role a oprávnění · OWNER</summary><small>Vlastník je chráněn a jeho roli nelze změnit.</small></details>':ownerAccess?'<details class="admin-role-editor"><summary>Role a oprávnění · '+esc(role)+'</summary><label>Role<select data-user-role-select><option value="USER" '+(role==='USER'?'selected':'')+'>USER</option><option value="MODERATOR" '+(role==='MODERATOR'?'selected':'')+'>MODERATOR</option><option value="ADMIN" '+(role==='ADMIN'?'selected':'')+'>ADMIN</option></select></label><div class="admin-permission-list">'+permissions+'</div><label>Důvod změny<input type="text" data-role-reason maxlength="500" placeholder="Proč se role mění"></label><button type="button" class="secondary" data-role-save data-user-id="'+esc(user.id)+'">Uložit roli</button></details>':'';
      const canSuspend=ownerAccess||accessPermissions.includes('users.suspend'),canReset=ownerAccess||accessPermissions.includes('users.reset_password');
      const resetAction=!isOwner&&canReset?'<button type="button" class="secondary" data-user-reset data-user-id="'+esc(user.id)+'">Poslat odkaz pro obnovu hesla</button>':'';
      const accountActions=isOwner?'<small class="admin-action-note">Účet vlastníka nelze z této tabulky pozastavit.</small>':!canSuspend?'<small class="admin-action-note">Bez oprávnění k pozastavení účtu.</small>':(user.is_banned?'<button type="button" class="secondary" data-user-action="unban" data-user-id="'+esc(user.id)+'">Odblokovat účet</button>':'<label class="admin-ban-duration">Délka pozastavení<select aria-label="Délka pozastavení" data-user-ban-duration><option value="24h">24 hodin</option><option value="7d">7 dní</option><option value="30d">30 dní</option><option value="permanent">Trvale</option></select></label><button type="button" class="secondary" data-user-action="ban" data-user-id="'+esc(user.id)+'">Pozastavit účet</button>')+resetAction;
      const date=value=>value?new Intl.DateTimeFormat('cs-CZ',{dateStyle:'medium'}).format(new Date(value)):'—';
      const lastLogin=user.last_sign_in_at?new Intl.DateTimeFormat('cs-CZ',{dateStyle:'short',timeStyle:'short'}).format(new Date(user.last_sign_in_at)):'Zatím se nepřihlásil';
      const hostStorage=user.yamahostStorage;
      const storageRow=ownerAccess?'<div class="admin-user-storage '+(hostStorage?'':'unavailable')+'"><small>YamaHost · cloudové úložiště</small>'+(hostStorage?'<strong>'+esc((hostStorage.usedBytes/1000000).toLocaleString('cs-CZ',{maximumFractionDigits:2})+' / '+(hostStorage.limitBytes/1000000).toLocaleString('cs-CZ',{maximumFractionDigits:0})+' MB')+'</strong><progress max="'+Number(hostStorage.limitBytes)+'" value="'+Number(hostStorage.usedBytes)+'" aria-label="Využití YamaHostu"></progress><span>'+Number(hostStorage.serverCount)+' serverů · volno '+esc((hostStorage.freeBytes/1000000).toLocaleString('cs-CZ',{maximumFractionDigits:2})+' MB')+'</span>':'<strong>Údaj se nepodařilo načíst</strong>')+'</div>'+(ownerAccess?'<button type="button" class="secondary admin-host-toggle" data-host-list data-user-id="'+esc(user.id)+'">Zobrazit servery</button><div class="admin-host-servers" data-host-servers="'+esc(user.id)+'" hidden></div>':''):'';
      return '<li class="admin-user-card '+(user.is_banned?'is-suspended':'')+'"><div class="admin-user-heading"><div class="admin-user-avatar" aria-hidden="true">'+esc(display.slice(0,1).toLocaleUpperCase('cs-CZ'))+'</div><div class="admin-user-identity"><strong>'+esc(display)+'</strong><span>@'+esc(user.username||'bez uživatelského jména')+'</span><small>'+esc(user.email||'E-mail není dostupný')+'</small></div><span class="admin-user-status '+(user.is_banned?'is-suspended':'')+'">'+(user.is_banned?'Pozastavený':'Aktivní')+'</span></div><div class="admin-user-meta"><span><small>Registrace</small><strong>'+esc(date(user.created_at))+'</strong></span><span><small>Poslední přihlášení</small><strong>'+esc(lastLogin)+'</strong></span><span class="admin-user-id"><small>ID účtu</small><code>'+esc(user.id)+'</code></span></div>'+storageRow+roleEditor+'<div class="admin-user-actions">'+accountActions+'</div></li>';
    }).join('')+'</ul>':'<p>Tomuto hledání neodpovídá žádný účet.</p>';
  }
  function syncRoleCard(card){if(!card)return;const role=card.querySelector('[data-user-role-select]')?.value||'USER';for(const input of card.querySelectorAll('[data-role-permission]')){const allowed=role==='ADMIN'||(role==='MODERATOR'&&['users.read','users.suspend'].includes(input.dataset.rolePermission));input.disabled=!allowed;if(!allowed)input.checked=false;}const permissions=new Map([...card.querySelectorAll('[data-role-permission]')].map(input=>[input.dataset.rolePermission,input]));if(permissions.get('users.suspend')?.checked)permissions.get('users.read').checked=true;if(permissions.get('storage.delete')?.checked)permissions.get('storage.read').checked=true;}
  function renderStorage(data){const root=document.querySelector('[data-storage-content]');if(!root)return;const bucketRows=(data.buckets||[]).map(bucket=>'<tr><td>'+esc(bucket.name)+'</td><td>'+Number(bucket.file_count||0)+'</td><td>'+esc(formatBytes(bucket.bytes))+'</td><td>'+esc(bucket.file_size_limit?formatBytes(bucket.file_size_limit):'Bez limitu')+'</td><td>'+(bucket.public?'Veřejné':'Soukromé')+'</td></tr>').join('');const objectRows=(data.objects||[]).map(item=>'<tr><td>'+esc(item.bucket_id)+'</td><td><code>'+esc(item.path)+'</code></td><td>'+esc(formatBytes(item.size))+'</td><td>'+(ownerAccess||accessPermissions.includes('storage.delete')?'<button class="secondary admin-storage-delete" type="button" data-storage-delete data-bucket="'+esc(item.bucket_id)+'" data-path="'+esc(item.path)+'">Smazat…</button>':'—')+'</td></tr>').join('');root.innerHTML='<h4>Úložiště</h4><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Název</th><th>Soubory</th><th>Využito</th><th>Limit souboru</th><th>Přístup</th></tr></thead><tbody>'+bucketRows+'</tbody></table></div><h4>Soubory a metadata</h4><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Úložiště</th><th>Cesta</th><th>Velikost</th><th>Akce</th></tr></thead><tbody>'+objectRows+'</tbody></table></div>'+(data.truncated?'<p class="caption">Výpis dosáhl bezpečného limitu '+Number(data.object_limit||5000)+' položek; součty jsou neúplné. Nejde o úplný stav úložiště.</p>':'<p class="caption">Úplný přehled metadat je načten. Obsah souborů zůstává skrytý.</p>');}
  function renderAudit(data){const root=document.querySelector('[data-storage-content]');if(!root)return;const rows=(data.entries||[]).map(row=>'<tr><td>'+esc(new Intl.DateTimeFormat('cs-CZ',{dateStyle:'short',timeStyle:'short'}).format(new Date(row.created_at)))+'</td><td>'+esc(row.action)+'</td><td>'+esc(row.bucket_id)+'</td><td><code>'+esc(row.object_path)+'</code></td><td>'+esc(formatBytes(row.object_size))+'</td><td>'+esc(row.outcome)+'</td></tr>').join('');root.innerHTML='<h4>Posledních 100 úkonů</h4><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Čas</th><th>Akce</th><th>Úložiště</th><th>Cesta</th><th>Velikost</th><th>Výsledek</th></tr></thead><tbody>'+rows+'</tbody></table></div>'+(rows?'':'<p>Audit zatím neobsahuje žádné úkony.</p>');}
  function renderRoleAudit(data){const root=document.querySelector('[data-role-audit-content]');if(!root)return;const rows=(data.entries||[]).map(row=>'<tr><td>'+esc(new Intl.DateTimeFormat('cs-CZ',{dateStyle:'short',timeStyle:'short'}).format(new Date(row.created_at)))+'</td><td>'+esc(row.target_user_id)+'</td><td>'+esc(row.previous_role||'USER')+' → '+esc(row.next_role)+'</td><td>'+esc((row.next_permissions||[]).join(', ')||'Bez dodatečných oprávnění')+'</td><td>'+esc(row.reason)+'</td></tr>').join('');root.innerHTML='<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Čas</th><th>Účet ID</th><th>Změna</th><th>Oprávnění</th><th>Důvod</th></tr></thead><tbody>'+rows+'</tbody></table></div>'+(rows?'':'<p>Historie změn rolí je zatím prázdná.</p>');}
  function renderUserAudit(data){const root=document.querySelector('[data-user-audit-content]');if(!root)return;const rows=(data.entries||[]).map(row=>'<tr><td>'+esc(new Intl.DateTimeFormat('cs-CZ',{dateStyle:'short',timeStyle:'short'}).format(new Date(row.created_at)))+'</td><td>'+esc(row.action)+'</td><td>'+esc(row.target_user_id)+'</td><td>'+esc(row.actor_user_id)+'</td><td>'+esc(row.outcome)+'</td><td>'+esc(row.reason)+'</td></tr>').join('');root.innerHTML='<h4>Posledních 100 úkonů účtů</h4><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Čas</th><th>Úkon</th><th>Cílový účet</th><th>Správce</th><th>Výsledek</th><th>Důvod</th></tr></thead><tbody>'+rows+'</tbody></table></div>'+(rows?'':'<p>Historie úkonů účtů je zatím prázdná.</p>');}
  function formatBytes(value){const n=Math.max(0,Number(value)||0);if(n<1024)return n+' B';const units=['kB','MB','GB','TB'];let size=n/1024,i=0;while(size>=1024&&i<units.length-1){size/=1024;i++}return size.toLocaleString('cs-CZ',{maximumFractionDigits:1})+' '+units[i];}
  function renderHostServers(panel,data){const labels={valheim:'Valheim','7dtd':'7 Days to Die',forest:'The Forest'},states={hosting:'Běží',offline:'Vypnutý','host-unreachable':'Hostitel nedostupný',starting:'Spouští se',stopping:'Zastavuje se'};const rows=(data.servers||[]).map(server=>'<article class="admin-host-server"><div><strong>'+esc(server.name)+'</strong><span>'+esc(labels[server.game]||server.game)+' · '+esc(states[server.state]||server.state)+'</span></div><small>Úložiště '+esc(formatBytes(server.storageBytes))+' · zálohy '+Number(server.historicalBackups||0)+' · verze světa '+Number(server.headVersion||0)+'</small><div class="admin-host-actions"><button type="button" class="secondary" data-host-action="stop" data-server-id="'+esc(server.id)+'" '+(server.state==='hosting'?'':'disabled')+'>Bezpečně vypnout</button><button type="button" class="secondary" data-host-action="restart" data-server-id="'+esc(server.id)+'" '+(server.state==='hosting'?'':'disabled')+'>Restartovat</button></div></article>').join('');panel.innerHTML=rows||'<p>Účet zatím nemá aktivní YamaHost servery.</p>';}
  async function load(){const state=document.querySelector('.admin-state'),content=document.querySelector('.admin-content');if(!state||!content)return;state.hidden=false;content.hidden=true;state.textContent='Ověřuji přístup…';try{const {sb,access}=await verify();admin=true;ownerAccess=access.is_owner===true;accessPermissions=access.permissions||[];const roleBadge=document.querySelector('[data-admin-role]');if(roleBadge)roleBadge.textContent=access.role||'USER';for(const section of document.querySelectorAll('[data-permission]'))section.hidden=!ownerAccess&&!accessPermissions.includes(section.dataset.permission);for(const section of document.querySelectorAll('[data-owner-only]'))section.hidden=!ownerAccess;const usersSection=document.querySelector('[data-permission="users.read"]');if(ownerAccess||accessPermissions.includes('users.read')){const result=await invoke(sb,'list',{perPage:1000});let users=result.users||[];const roleResult=await invoke(sb,'role-list'),roles=new Map((roleResult.roles||[]).map(item=>[item.user_id,item]));users=users.map(user=>{const assigned=roles.get(user.id);return {...user,role:assigned?.role||'USER',permissions:assigned?.permissions||[]};});const storageSort=document.querySelector('#admin-user-sort option[value="storage"]');if(storageSort)storageSort.hidden=!access.is_owner;let storageByUser=new Map();const storageStatus=document.querySelector('[data-yamahost-storage-status]');if(access.is_owner){if(storageStatus)storageStatus.textContent='Načítám ověřenou spotřebu YamaHostu…';try{const {data:sessionData,error:sessionError}=await sb.auth.getSession();if(sessionError||!sessionData?.session?.access_token)throw new Error('Přihlášení už není platné.');const response=await fetch('https://yamahost.yamachat.eu/api/yamahost/admin/storage-usage',{method:'POST',headers:{Authorization:'Bearer '+sessionData.session.access_token,'Content-Type':'application/json'},body:JSON.stringify({user_ids:users.map(item=>item.id)}),cache:'no-store',redirect:'error'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Řídicí služba YamaHostu nevrátila spotřebu.');storageByUser=new Map((data.users||[]).map(item=>[item.user_id,item]));if(storageStatus)storageStatus.textContent='Spotřeba YamaHostu je ověřená pro '+storageByUser.size+' účtů.';}catch(error){if(storageStatus)storageStatus.textContent='Spotřebu YamaHostu se nepodařilo ověřit: '+(error.message||'služba není dostupná');}users=users.map(item=>({...item,yamahostStorage:storageByUser.get(item.id)||null}));}renderUsers(users);for(const select of document.querySelectorAll('[data-user-role-select]'))syncRoleCard(select.closest('li'));}else if(usersSection)usersSection.hidden=true;const roleAuditButton=document.querySelector('[data-role-audit]');if(roleAuditButton)roleAuditButton.hidden=!ownerAccess;state.hidden=true;content.hidden=false;}catch(error){admin=false;state.textContent=error.message||'Správu se nepodařilo načíst.';}}
  document.addEventListener('change',event=>{if(event.target.matches('#admin-user-sort')){const target=document.querySelector('[data-admin-users]');try{renderUsers(JSON.parse(target?.dataset.userRows||'[]'))}catch{}return;}if(event.target.matches('[data-user-role-select]'))syncRoleCard(event.target.closest('li'));if(event.target.matches('[data-role-permission]')){const card=event.target.closest('li'),key=event.target.dataset.rolePermission,permissions=new Map([...card.querySelectorAll('[data-role-permission]')].map(input=>[input.dataset.rolePermission,input]));if(key==='users.read'&&!event.target.checked){if(permissions.get('users.suspend'))permissions.get('users.suspend').checked=false;if(permissions.get('users.reset_password'))permissions.get('users.reset_password').checked=false;}if(key==='storage.read'&&!event.target.checked&&permissions.get('storage.delete'))permissions.get('storage.delete').checked=false;if(event.target.checked&&(key==='users.suspend'||key==='users.reset_password')&&permissions.get('users.read'))permissions.get('users.read').checked=true;if(event.target.checked&&key==='storage.delete'&&permissions.get('storage.read'))permissions.get('storage.read').checked=true;}});
  document.addEventListener('input',event=>{if(event.target.matches('#admin-user-search')||event.target.matches('#admin-user-sort')){const target=document.querySelector('[data-admin-users]');try{renderUsers(JSON.parse(target?.dataset.userRows||'[]'))}catch{}}});
  document.addEventListener('click',async event=>{const refresh=event.target.closest('[data-storage-refresh]'),audit=event.target.closest('[data-storage-audit]'),remove=event.target.closest('[data-storage-delete]'),userAction=event.target.closest('[data-user-action]'),roleSave=event.target.closest('[data-role-save]'),roleAudit=event.target.closest('[data-role-audit]'),userAudit=event.target.closest('[data-user-audit]'),resetUser=event.target.closest('[data-user-reset]'),hostList=event.target.closest('[data-host-list]'),hostAction=event.target.closest('[data-host-action]');if(!refresh&&!audit&&!remove&&!userAction&&!roleSave&&!roleAudit&&!userAudit&&!resetUser&&!hostList&&!hostAction)return;const status=document.querySelector('[data-storage-status]'),root=document.querySelector('[data-storage-content]'),userStatus=document.querySelector('[data-user-admin-status]');for(const button of [refresh,audit,remove,userAction,roleSave,roleAudit,userAudit,resetUser,hostList,hostAction].filter(Boolean))button.disabled=true;try{const {sb}=await verify();if(hostList){const userId=hostList.dataset.userId,panel=document.querySelector('[data-host-servers="'+userId+'"]');if(!panel)return;panel.hidden=!panel.hidden;if(panel.hidden)return;panel.innerHTML='<p>Načítám servery…</p>';renderHostServers(panel,await hostAdminRequest(sb,'admin/user-servers',{user_id:userId}));return;}if(hostAction){const operation=hostAction.dataset.hostAction,reason=prompt('Zadej důvod této správcovské akce:');if(reason===null)return;if(reason.trim().length<2)throw new Error('Důvod musí mít alespoň dva znaky.');const verb=operation==='stop'?'bezpečně vypnout':'restartovat';if(!confirm('Opravdu chceš '+verb+' tento YamaHost server?'))return;await hostAdminRequest(sb,'admin/server-action',{server_id:hostAction.dataset.serverId,operation,reason:reason.trim()});if(userStatus)userStatus.textContent='Požadavek byl zařazen a zaznamenán do historie serveru.';const panel=hostAction.closest('[data-host-servers]'),userId=hostAction.closest('.admin-user-card')?.querySelector('[data-host-list]')?.dataset.userId;if(panel&&userId)renderHostServers(panel,await hostAdminRequest(sb,'admin/user-servers',{user_id:userId}));return;}if(resetUser){const reason=prompt('Zadej důvod odeslání odkazu pro obnovu hesla:');if(reason===null)return;if(reason.trim().length<2)throw new Error('Důvod musí mít alespoň dva znaky.');if(!confirm('Odeslat uživateli e-mail s odkazem pro obnovu hesla?'))return;await invoke(sb,'reset-password',{user_id:resetUser.dataset.userId,reason:reason.trim()});if(userStatus)userStatus.textContent='Odkaz pro obnovu hesla byl odeslán a úkon zaznamenán.';return;}if(roleSave){const card=roleSave.closest('li'),role=card?.querySelector('[data-user-role-select]')?.value||'USER',permissions=role==='USER'?[]:[...card.querySelectorAll('[data-role-permission]:checked')].map(input=>input.dataset.rolePermission),reason=card?.querySelector('[data-role-reason]')?.value.trim()||'';if(reason.length<2)throw new Error('Doplň důvod změny role.');if(!confirm('Uložit roli '+role+' a vybraná oprávnění pro tento účet?'))return;await invoke(sb,'role-set',{user_id:roleSave.dataset.userId,role,permissions,reason});if(userStatus)userStatus.textContent='Role a oprávnění byly uloženy do auditované historie.';await load();return;}if(roleAudit){if(userStatus)userStatus.textContent='Načítám audit změn rolí…';renderRoleAudit(await invoke(sb,'role-audit'));if(userStatus)userStatus.textContent='Historie změn rolí načtena.';return;}if(userAudit){if(userStatus)userStatus.textContent='Načítám historii úkonů účtů…';renderUserAudit(await invoke(sb,'user-audit'));if(userStatus)userStatus.textContent='Historie úkonů účtů načtena.';return;}if(userAction){const userId=userAction.dataset.userId,action=userAction.dataset.userAction;if(action==='ban'){const duration=userAction.parentElement.querySelector('[data-user-ban-duration]')?.value||'24h';const reason=prompt('Zadej důvod pozastavení účtu:');if(reason===null)return;if(reason.trim().length<2)throw new Error('Důvod musí mít alespoň dva znaky.');if(!confirm('Opravdu pozastavit tento účet?'))return;await invoke(sb,'ban',{user_id:userId,duration,reason:reason.trim()});if(userStatus)userStatus.textContent='Účet byl pozastaven a změna zaznamenána.';}else{if(!confirm('Opravdu odblokovat tento účet?'))return;await invoke(sb,'unban',{user_id:userId,reason:'Odblokováno vlastníkem v Yamaportal.'});if(userStatus)userStatus.textContent='Účet byl odblokován a změna zaznamenána.';}await load();return;}if(remove){const bucket=remove.dataset.bucket,path=remove.dataset.path;if(!confirm('Trvale odstranit tento soubor z Yamachat Storage?\n\n'+bucket+' / '+path+'\n\nObsah nepůjde obnovit.'))return;const typed=prompt('Pro potvrzení napiš přesně cestu souboru:');if(typed!==path){if(status)status.textContent='Cesta nesouhlasí. Soubor nebyl smazán.';return}if(status)status.textContent='Zapisuji audit a mažu soubor…';await invoke(sb,'storage-delete',{bucket_id:bucket,path,confirm_path:typed});if(status)status.textContent='Soubor byl odstraněn a úkon zaznamenán do auditu.';const data=await invoke(sb,'storage-summary');renderStorage(data);return}if(audit){if(status)status.textContent='Načítám auditní historii…';renderAudit(await invoke(sb,'storage-audit'));if(status)status.textContent='Historie údržby načtena.';return}if(status)status.textContent='Načítám metadata úložišť…';const data=await invoke(sb,'storage-summary');renderStorage(data);if(status)status.textContent=data.truncated?'Přehled načten částečně; součty jsou označené jako neúplné.':'Přehled úložišť načten.';}catch(error){if(status)status.textContent=error.message||'Operace se nepodařila.';if(root&&!root.children.length)root.textContent='';}finally{for(const button of [refresh,audit,remove,userAction,roleSave,roleAudit,userAudit,resetUser,hostList,hostAction].filter(Boolean))button.disabled=false;}});
  document.addEventListener('submit',async event=>{const form=event.target.closest('[data-admin-broadcast]');if(!form)return;event.preventDefault();const button=form.querySelector('[type=submit]'),status=form.querySelector('[data-admin-status]'),values=new FormData(form);button.disabled=true;status.textContent='Ověřuji oprávnění a připravuji doručení…';try{if(!values.get('confirm'))throw new Error('Potvrď prosím, že jde o zprávu všem uživatelům.');const {sb,user}=await verify();const {data:profiles,error}=await sb.from('profiles').select('id').limit(1001);if(error)throw new Error('Seznam příjemců se nepodařilo ověřit. Zpráva nebyla odeslána.');if((profiles||[]).length>1000)throw new Error('Počet účtů překročil bezpečný limit 1 000. Zpráva nebyla odeslána.');const recipients=(profiles||[]).map(p=>p.id);if(!recipients.length)throw new Error('Nebyly nalezeny žádné účty.');const message={title:String(values.get('title')||'').trim(),body:String(values.get('body')||'').trim(),kind:String(values.get('kind')||'info'),created_by:user.id};if(!message.title||!message.body)throw new Error('Vyplň nadpis i zprávu.');const {error:sendError}=await sb.from('account_messages').insert(recipients.map(recipient_user_id=>({...message,recipient_user_id})));if(sendError)throw new Error('Odeslání se nepodařilo.');status.textContent='Zpráva byla uložena do schránky '+recipients.length+' uživatelů.';form.reset();}catch(error){status.textContent=error.message||'Zpráva nebyla odeslána.';}finally{button.disabled=false;}});
  window.YamaAdminUI=Object.freeze({isAdmin,init,markup,load});
})(window);
